Here is an optimized primality test running in O(sqrt(n)) time:

```python
def is_prime(number: int) -> bool:
    """Determine if an integer is a prime number."""
    if not isinstance(number, int) or number < 2:
        return False
    if number in (2, 3):
        return True
    if number % 2 == 0 or number % 3 == 0:
        return False

    # Check potential divisors up to sqrt(number), stepping by 6 (6k +/- 1)
    divisor = 5
    while divisor * divisor <= number:
        if number % divisor == 0 or number % (divisor + 2) == 0:
            return False
        divisor += 6

    return True

print(is_prime(29))  # True
print(is_prime(100)) # False
```

Here is an object-oriented Stack using a Python list as the backing store:

```python
class Stack:
    def __init__(self):
        self._items = []

    def push(self, item):
        self._items.append(item)

    def pop(self):
        if self.is_empty():
            raise IndexError("pop from empty stack")
        return self._items.pop()

    def peek(self):
        if self.is_empty():
            raise IndexError("peek from empty stack")
        return self._items[-1]

    def is_empty(self) -> bool:
        return len(self._items) == 0

    def __len__(self) -> int:
        return len(self._items)

s = Stack()
s.push("A")
s.push("B")
print(s.peek())  # 'B'
print(s.pop())   # 'B'
```

Here is how to flatten nested lists of arbitrary depth:

```python
def flatten_deep(nested):
    flattened = []
    for item in nested:
        if isinstance(item, list):
            flattened.extend(flatten_deep(item))
        else:
            flattened.append(item)
    return flattened

nested_data = [1, [2, [3, 4], 5], [[6]], 7]
print(flatten_deep(nested_data))  # [1, 2, 3, 4, 5, 6, 7]
```

In a Binary Search Tree (BST), we exploit node values to find LCA in O(h) time:

```python
class TreeNode:
    def __init__(self, val, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def lowest_common_ancestor(root: TreeNode, p: int, q: int) -> TreeNode:
    curr = root
    while curr:
        if p < curr.val and q < curr.val:
            curr = curr.left
        elif p > curr.val and q > curr.val:
            curr = curr.right
        else:
            return curr
    return None
```

