Access query parameters using `request.args.get()`:

```python
from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route("/api/items")
def list_items():
    sort_dir = request.args.get("sort", default="asc", type=str)
    limit = request.args.get("limit", default=20, type=int)
    return jsonify({"sort": sort_dir, "limit": limit})
